code.cpp:
class Solution {
public:
    int findPairs(vector<int>& nums, int k) {
        unordered_map<int,int> freq;
        for (int x : nums) freq[x]++;
        int ans = 0;
        for (auto& [x, c] : freq) {
            if (k == 0) {
                if (c >= 2) ans++;
            } else {
                if (freq.count(x + k)) ans++;
            }
        }
        return ans;
    }
};
